const { EventEmitter } = require("node:events");

function crearCanalPedidos() {
  const emitter = new EventEmitter();
  let notificaciones = 0;
  emitter.on("pedido-creado", () => { notificaciones += 1; });
  return { emitter, getNotificaciones: () => notificaciones };
}

function contarUnaVez() {
  const emitter = new EventEmitter();
  let total = 0;
  emitter.once("cerrar", () => { total += 1; });
  emitter.emit("cerrar");
  emitter.emit("cerrar");
  return total;
}

module.exports = { crearCanalPedidos, contarUnaVez };

