}

challenges.solutionCode:
async function obtenerTodosLosLibros() {
  const libros = [];
  let pagina = 1;
  while (pagina !== null) {
    const response = await fetch(`/api/libros?page=${pagina}`);
    if (!response.ok) throw new Error("Falló la consulta de libros");
    const body = await response.json();
    libros.push(...body.items);
    pagina = body.nextPage;
  }
  return libros;
}

